ALLOWED_HOSTS = [
    "example.com",
    "api.example.org",
]

def is_allowed_url(url):
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        return False
    host = parsed.hostname or parsed.netloc
    if not host:
        return False
    # 只允许白名单域名，拒绝 IP 地址和子域（防止 SSRF）
    if host == "":
        return False
    if host in ALLOWED_HOSTS:
        return True
    # 拒绝 IP 直接访问（如 127.0.0.1、内网 IP）
    if host.replace(".", ".") in ["127.0.0.1", "localhost"] or host.startswith(("10.", "192.168.", "172.")):
        return False
    # 拒绝子域（防止 SSRF 绕过）
    if parsed.hostname != parsed.netloc:
        return False
    return True

@app.route("/proxy/fetch", methods=["GET"])
def fetch_url():
    """Fetch a remote resource on behalf of the user (e.g. for thumbnail generation)."""
    target_url = request.args.get("url", "")
    if not target_url:
        return jsonify({"error": "url parameter required"}), 400

    # 安全修复：白名单校验 + 拒绝 IP 和子域访问
    if not is_allowed_url(target_url):
        return jsonify({"error": "URL not allowed"}), 403

    try:
        resp = requests.get(target_url, timeout=10, allow_redirects=False)
        # 禁止重定向，防止 SSRF 绕过
        if resp.status_code == 302 or resp.status_code == 301:
            return jsonify({"error": "Redirect not allowed"}), 403
        return jsonify({
            "status": resp.status_code,
            "content_type": resp.headers.get("Content-Type", ""),
            "body": resp.text[:5000],
        })
    except Exception as e:
